const r = await tools.exec_command({cmd:`{ printf 'COMMAND: python integrity compare (corrected manifest key: link_target); operational workspace only\\n'; "$STAMPED_ASSESSMENT_PYTHON" - <<'PY'
import hashlib,json,os,stat
from pathlib import Path
m=json.load(open(os.environ["STAMPED_OPERATIONAL_MANIFEST"]))
root=Path(os.environ["STAMPED_JUDGE_TARGET"]); changes=[]; checked=0
for e in m["entries"]:
 p=e["path"]
 if not p.startswith("content/workspace/"): continue
 rel=p[len("content/workspace/"):]; q=root/rel
 try: st=q.lstat()
 except FileNotFoundError:
  changes.append({"path":rel,"change":"missing"}); continue
 checked+=1; kind=e.get("kind")
 if kind=="file":
  if not stat.S_ISREG(st.st_mode): changes.append({"path":rel,"change":"kind","expected":kind})
  else:
   h=hashlib.sha256(q.read_bytes()).hexdigest()
   if h!=e.get("sha256"): changes.append({"path":rel,"change":"sha256","expected":e.get("sha256"),"observed":h})
 elif kind=="symlink":
  t=os.readlink(q) if stat.S_ISLNK(st.st_mode) else None
  if t!=e.get("link_target"): changes.append({"path":rel,"change":"link_target","expected":e.get("link_target"),"observed":t})
 elif kind=="directory" and not stat.S_ISDIR(st.st_mode): changes.append({"path":rel,"change":"kind","expected":kind})
 if kind in ("file","symlink","directory") and stat.S_IMODE(st.st_mode)!=e.get("mode"):
  changes.append({"path":rel,"change":"mode","expected":e.get("mode"),"observed":stat.S_IMODE(st.st_mode)})
allowed={".git/annex/keysdb/db",".git/annex/keysdb/db-shm",".git/annex/keysdb/db-wal"}
result={"checked_manifest_entries":checked,"change_count":len(changes),"changes":changes,
 "classified_operational_metadata_only":bool(changes) and all(x["path"] in allowed for x in changes),
 "metadata_logical_equivalence":"not established"}
(Path(os.environ["STAMPED_JUDGE_OUTPUT"])/"integrity-comparison.json").write_text(json.dumps(result,indent=2)+"\\n")
print(json.dumps(result,indent=2))
PY
} > "$STAMPED_JUDGE_OUTPUT/commands/integrity-compare-corrected.txt" 2>&1
cat "$STAMPED_JUDGE_OUTPUT/integrity-comparison.json"`,yield_time_ms:30000,max_output_tokens:1000}); text(r.output)

